const numericIds = () => [...inlineNumericIds,
  ...Object.keys(loadPythonFixtureSuffixes(process.cwd(), inlineNumericIds))];
const firstLine = (error: unknown) => error instanceof Error ? error.message.split('\n')[0] : '';
const assertion = (message: string | RegExp) => (error: unknown) => error instanceof assert.AssertionError
  && (typeof message === 'string' ? firstLine(error) === message : message.test(firstLine(error)));
const reject = (label: string, run: () => unknown, diagnostic: string | RegExp) =>
  assert.throws(run, assertion(diagnostic), label);

// Required rows are frozen independently of the live arrays. Simultaneous omission
// from a live registry cannot silently shrink the expected set.
test('ranking and timing preserve every prior example and fixture row and add only the exact pair identities', () => {
  for (const required of requiredExamples) {
    expect(exampleChecks.filter(row => row[0] === required[0])).toEqual([required]);
  }
  expect(exampleChecks.filter(row => requiredExamples.some(required => required[0] === row[0]))).toEqual(requiredExamples);
  for (const required of requiredFixtures) {
    expect(pythonFixtureRegistrations.filter(row => row[0] === required[0])).toEqual([required]);
  }
  expect(pythonFixtureRegistrations.filter(row => requiredFixtures.some(required => required[0] === row[0]))).toEqual(requiredFixtures);
  validateExampleChecks(units, numericIds());
});

test('every example registration rejects its own deletion, duplication, unknown identity and kind reassignment', () => {
  const pythonIds = numericIds(); validateExampleChecks(units, pythonIds);
  for (const [index, [articleId, exampleId, kind]] of exampleChecks.entries()) {
    const rows = () => structuredClone(exampleChecks);
    reject(`missing exact article/example row ${articleId}`, () => validateExampleChecks(units, pythonIds, rows().filter((_, at) => at !== index)),
      kind === 'python' ? `Unused/reassigned numeric check: ${exampleId}` : `Unregistered example article: ${articleId}`);
    reject(`duplicate full example row ${articleId}`, () => validateExampleChecks(units, pythonIds, [...rows(), [...exampleChecks[index]]]),
      'Duplicate/overlapping example registration');
    reject(`duplicate article only ${articleId}`, () => validateExampleChecks(units, pythonIds, [...rows(), [articleId, 'unregistered-example', kind]]),
      'Duplicate/overlapping example registration');
    reject(`duplicate example only ${exampleId}`, () => validateExampleChecks(units, pythonIds, [...rows(), ['unregistered-article', exampleId, kind]]),
      'Duplicate/overlapping example registration');
    const article = rows(); article[index][0] = 'unregistered-article';
    reject(`unknown article substitution ${articleId}`, () => validateExampleChecks(units, pythonIds, article),
      kind === 'python' ? `Unregistered example article: ${articleId}` : 'Unknown observable-case article/example pair');
    const example = rows(); example[index][1] = 'unregistered-example';
    reject(`unknown example substitution ${exampleId}`, () => validateExampleChecks(units, pythonIds, example),
      kind === 'python' ? 'Missing numeric checks: unregistered-example' : 'Unknown observable-case article/example pair');
    const unknownKind = rows(); unknownKind[index][2] = 'optional';
    reject(`unknown check kind ${articleId}`, () => validateExampleChecks(units, pythonIds, unknownKind), 'Unknown example kind: optional');
    const reassigned = rows(); reassigned[index][2] = kind === 'python' ? 'observable-case' : 'python';
    reject(`reassigned actual example kind ${articleId}`, () => validateExampleChecks(units, pythonIds, reassigned),
      kind === 'python' ? `Cannot reassign numeric example: ${exampleId}` : `Missing numeric checks: ${exampleId}`);
  }
  for (const [index, id] of pythonIds.entries()) {
    reject(`missing Python check ${id}`, () => validateExampleChecks(units, pythonIds.filter((_, at) => at !== index)), `Missing numeric checks: ${id}`);
    reject(`duplicate Python check ${id}`, () => validateExampleChecks(units, [...pythonIds, id]), 'Duplicate Python check ID');
  }
  reject('unknown extra numeric check', () => validateExampleChecks(units, [...pythonIds, 'unregistered-numeric']), 'Unused/reassigned numeric check: unregistered-numeric');
});

test('every file fixture registration rejects its own deletion, missing file, unknown ID and duplicate path', () => {
  const validate = (rows: typeof pythonFixtureRegistrations) => {
    const loaded = loadPythonFixtureSuffixes(process.cwd(), inlineNumericIds, rows);
    validateExampleChecks(units, [...inlineNumericIds, ...Object.keys(loaded)]);
  };
  validate(pythonFixtureRegistrations);
  for (const [index, [id, path]] of pythonFixtureRegistrations.entries()) {
    const rows = () => structuredClone(pythonFixtureRegistrations);
    reject(`missing required fixture ${id}`, () => validate(rows().filter((_, at) => at !== index)), `Missing numeric checks: ${id}`);
    const missing = rows(); missing[index][1] = 'scripts/knowledge-fixtures/unregistered-missing-fixture.py';
    reject(`missing real fixture file ${id}`, () => validate(missing), 'Missing Python fixture: scripts/knowledge-fixtures/unregistered-missing-fixture.py');
    const unknown = rows(); unknown[index][0] = 'unregistered-fixture';
    reject(`unknown fixture ID ${id}`, () => validate(unknown), `Missing numeric checks: ${id}`);
    reject(`duplicate complete fixture row ${id}`, () => validate([...rows(), [id, path]]), `Duplicate fixture example ID: ${id}`);
    reject(`duplicate fixture ID ${id}`, () => validate([...rows(), [id, 'scripts/knowledge-fixtures/unregistered-missing-fixture.py']]), `Duplicate fixture example ID: ${id}`);
    reject(`duplicate real fixture path ${id}`, () => validate([...rows(), ['unregistered-fixture', path]]), `Duplicate fixture path: ${path}`);
    const collision = rows(); collision[index][0] = inlineNumericIds[0];
    reject(`inline collision at ${id}`, () => validate(collision), `Fixture collides with inline example: ${inlineNumericIds[0]}`);
  }
});

test('ranking sibling and reused efficiency preserve original concepts, canonical parents and old relative order', () => {
  expect(graph.nodes.filter(node => node.kind === 'concept').map(node => node.id).sort()).toEqual(preservedConceptIds);
  expect(preservedConceptIds).toHaveLength(407); expect(original603Ids).toHaveLength(603);
  const ids = graph.nodes.map(node => node.id); expect(new Set(ids).size).toBe(ids.length);
  for (const id of original603Ids) expect(ids.filter(value => value === id)).toHaveLength(1);
  for (const prior of preservedNodes) {
    const actual = graph.nodes.find(node => node.id === prior.id)!;
    expect(actual, prior.id).toBeTruthy();
    for (const key of ['id', 'kind', 'parentId', 'label'] as const) expect(actual[key] ?? null, `${prior.id}:${key}`).toBe(prior[key]);
  }
  const parent = 'branch:llm:rankings', actual = graph.nodes.filter(node => node.parentId === parent).map(node => node.id);
  const newLeaf = `${parent}/ranking-metrics`, old = oldRankingChildren.map(id => `${parent}/${id}`);
  expect(actual.filter(id => old.includes(id))).toEqual(old);
  const at = actual.indexOf(`${parent}/metrics`);
  expect(actual.slice(at, at + 3)).toEqual([`${parent}/metrics`, newLeaf, `${parent}/calibration`]);
  expect(graph.nodes.filter(node => node.id === newLeaf)).toHaveLength(1);
  expect(graph.nodes.find(node => node.id === parent)!.embeddedArticleId).toBeUndefined();
  const efficiency = graph.nodes.find(node => node.id === `${parent}/efficiency`)!;
  expect(original603Ids).toContain(efficiency.id);
  expect(efficiency.label).toBe('时延、速度、吞吐与费用条件');
  expect(efficiency.conceptRefs).toEqual(['concept:ttft', 'concept:tps', 'concept:throughput', 'concept:tail-latency']);
  for (const [path, article] of [['metrics', 'classification-accuracy-precision-recall-f1'], ['calibration', 'probability-calibration-brier-bins'],
    ['datasets', 'evaluation-dataset-target-coverage'], ['protocol', 'benchmark-protocol-comparable-runs'], ['methodology', 'statistical-inference-confidence-interval']]) {
    expect(graph.nodes.find(node => node.id === `${parent}/${path}`)!.embeddedArticleId).toBe(article);
  }
  expect(graph.nodes.find(node => node.id === `${parent}/metrics`)!.conceptRefs).toEqual(['concept:accuracy-f1', 'concept:precision-recall']);
  expect(graph.nodes.find(node => node.id === `${parent}/methodology`)!.conceptRefs).toEqual(['concept:benchmark-protocol', 'concept:confidence-interval']);
  expect(graph.nodes.find(node => node.id === 'concept:ranking-metrics')!.parentId).toBe('topic:task-metrics');
  for (const id of ['concept:ttft', 'concept:tps', 'concept:throughput', 'concept:tail-latency'])
    expect(graph.nodes.find(node => node.id === id)!.parentId).toBe('topic:efficiency-metrics');
});

test('pair navigation retains every pre-pair edge object and has exactly the three scoped new reference/navigation edges', () => {
  const oldIds = new Set(preservedEdges.map(edge => edge.id));
  expect(graph.edges.filter(edge => oldIds.has(edge.id))).toEqual(preservedEdges);
  const allIds = graph.edges.map(edge => edge.id); expect(new Set(allIds).size).toBe(allIds.length);
  const expected = [
    ['nav:branch:llm:rankings>branch:llm:rankings/ranking-metrics', 'branch:llm:rankings', 'branch:llm:rankings/ranking-metrics', 'browse_child'],
    ['references:branch:llm:rankings/ranking-metrics>concept:ranking-metrics', 'branch:llm:rankings/ranking-metrics', 'concept:ranking-metrics', 'references'],
    ['references:branch:llm:rankings/efficiency>concept:tail-latency', 'branch:llm:rankings/efficiency', 'concept:tail-latency', 'references'],
  ];
  for (const [id, source, target, type] of expected) {
    const edge = graph.edges.filter(edge => edge.id === id); expect(edge).toHaveLength(1);
    expect(edge[0]).toMatchObject({ id, source, target, type, assertionStatus: 'editorial' });
    expect(edge[0].routeId).toBeUndefined();
  }
  // Scope new-edge checks to this pair; later independent batches may add unrelated navigation.
  const related = new Set(['branch:llm:rankings/ranking-metrics', 'branch:llm:rankings/efficiency',
    'concept:ranking-metrics', 'concept:ttft', 'concept:tps', 'concept:throughput', 'concept:tail-latency']);
  expect(graph.edges.filter(edge => !oldIds.has(edge.id) && (related.has(edge.source) || related.has(edge.target))).map(edge => edge.id).sort())
    .toEqual(expected.map(row => row[0]).sort());
});
